INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich bei der Arbeit an einem Server immer den Strom abschalten muss?', 2, '[{"text": "Ja", "correct": true, "because": "Vermeidet Stromschläge"}, {"text": "Nein", "correct": false, "because": "Nur bei speziellen Geräten sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt mich am besten, wenn ich an elektrischen Geräten arbeite?', 3, '[{"text": "Freischalten der Stromversorgung", "correct": true, "because": "Verhindert Spannung"}, {"text": "Schnelles Arbeiten", "correct": false, "because": "Erhöht Risiko"}, {"text": "Helle Beleuchtung", "correct": false, "because": "Kein Schutz vor Strom"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorkehrungen sind bei der Arbeit an IT-Hardware wichtig?', 5, '[{"text": "Erdung prüfen", "correct": true, "because": "Leitet Überspannung ab"}, {"text": "Isolierte Werkzeuge", "correct": true, "because": "Vermeidet Stromfluss"}, {"text": "Hohe Luftfeuchtigkeit", "correct": false, "because": "Kann Schäden verursachen"}, {"text": "Lautes Radio", "correct": false, "because": "Irrelevant für Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein FI-Schalter schützt vor Stromschlägen. b) Normale Handschuhe reichen für Hochspannung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Normale Handschuhe schützen nicht ausreichend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen PC repariere?', 4, '[{"text": "Kabelzustand", "correct": false, "because": "Defekte Kabel sind gefährlich"}, {"text": "Spannungsfreiheit", "correct": false, "because": "Muss geprüft werden"}, {"text": "Farbe des Gehäuses", "correct": true, "because": "Irrelevant für Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Netzteil auch ausgeschaltet gefährlich sein kann. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Kondensatoren speichern Spannung"}, {"text": "Nein", "correct": false, "because": "Restspannung bleibt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wähle ich für die Arbeit an einer Steckdose?', 3, '[{"text": "Spannungsprüfer", "correct": true, "because": "Prüft Spannungsfreiheit"}, {"text": "Schraubendreher", "correct": false, "because": "Kein Sicherheitswerkzeug"}, {"text": "Zange", "correct": false, "because": "Nicht für Spannungsprüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren reduzieren Risiken bei der Arbeit mit Hardware?', 5, '[{"text": "Schutzhandschuhe", "correct": true, "because": "Isoliert gegen Strom"}, {"text": "Arbeit im Team", "correct": true, "because": "Erhöht Kontrolle"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Erhöht Fehlerquote"}, {"text": "Hohe Temperatur", "correct": false, "because": "Kann Geräte schädigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) nasse Hände bei Elektroarbeiten gefährlich sind und b) ein Holzfußboden immer sicher ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Holz kann leiten, wenn feucht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um sicher an einem Server zu arbeiten?', 4, '[{"text": "Spannungsfreies System", "correct": false, "because": "Schützt vor Stromschlag"}, {"text": "Schutzmaßnahmen", "correct": false, "because": "Vermeiden Unfälle"}, {"text": "Lautsprecher", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein FI-Schalter Pflicht in jedem Serverraum?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Normen"}, {"text": "Ja", "correct": false, "because": "Nicht universell vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsmaßnahmen sind bei der Arbeit an IT-Geräten entscheidend?', 4, '[{"text": "Geräte ausschalten", "correct": true, "because": "Verhindert Spannung"}, {"text": "Erdung sicherstellen", "correct": true, "because": "Leitet Strom ab"}, {"text": "Schnelles Arbeiten", "correct": false, "because": "Erhöht Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Stromschlag nur bei Hochspannung gefährlich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schon Niederspannung ist gefährlich"}, {"text": "Ja", "correct": false, "because": "Auch 230V sind riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Netzteil austausche?', 3, '[{"text": "Spannungsfreiheit prüfen", "correct": true, "because": "Schützt vor Unfällen"}, {"text": "Schnelle Montage", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Optische Kontrolle", "correct": false, "because": "Nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Überspannungsschutz schützt Geräte. b) Er schützt auch Menschen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Menschen brauchen andere Maßnahmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein isolierter Arbeitsplatz?', 5, '[{"text": "Schutz vor Stromschlag", "correct": true, "because": "Verhindert Stromfluss"}, {"text": "Bessere Erdung", "correct": false, "because": "Erdung ist separat"}, {"text": "Höhere Produktivität", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Arbeit an einem offenen PC unwichtig?', 3, '[{"text": "Antistatische Maßnahmen", "correct": false, "because": "Schützt Komponenten"}, {"text": "Spannungsfreiheit", "correct": false, "because": "Schützt vor Strom"}, {"text": "Hintergrundmusik", "correct": true, "because": "Kein Einfluss auf Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt ein antistatisches Armband auch vor Stromschlägen?', 3, '[{"text": "Nein", "correct": true, "because": "Nur gegen statische Entladung"}, {"text": "Ja", "correct": false, "because": "Kein Schutz vor Wechselstrom"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Serverraum immer eine Notabschaltung braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherheitsvorschrift"}, {"text": "Nein", "correct": false, "because": "Für Notfälle vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorgehensweise wähle ich, um ein Kabel sicher zu prüfen?', 4, '[{"text": "Spannungsprüfer verwenden", "correct": true, "because": "Bestätigt Spannungsfreiheit"}, {"text": "Visuelle Inspektion", "correct": false, "because": "Nicht ausreichend"}, {"text": "Kabel schütteln", "correct": false, "because": "Keine Sicherheitsprüfung"}]');
